<script lang="ts">
 import PageHeader from '$lib/components/PageHeader.svelte'; import { downloadAdminLogs } from '$lib/api/audit'; import { me } from '$lib/api/auth'; import type { MeResponse } from '$lib/api/types'; import { onMount } from 'svelte'; let user=$state<MeResponse|null>(null),loading=$state(true),exporting=$state(false),errorMessage=$state(''); onMount(async()=>{try{user=(await me()).data}catch(e){errorMessage=e instanceof Error?e.message:'系统信息加载失败'}finally{loading=false}}); async function exportLogs(){exporting=true;try{const blob=await downloadAdminLogs();const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='admin-operation-logs.csv';a.click();URL.revokeObjectURL(url)}catch(e){errorMessage=e instanceof Error?e.message:'全局日志导出失败'}finally{exporting=false}}
</script>
<PageHeader title="系统设置" eyebrow="System" description="查看当前系统权限，并导出全局操作日志。" />{#if loading}<section class="workspace-card state-box">正在加载系统信息…</section>{:else if user}<div class="system-grid"><section class="workspace-card"><h2>当前权限</h2><p>{user.system_role==='super_admin'?'你拥有超级管理员权限，可以查看全部部门和导出全局日志。':'当前账号是普通用户，系统管理操作需要超级管理员权限。'}</p><div class="role-badge">{user.system_role}</div></section><section class="workspace-card"><h2>全局操作日志</h2><p>导出所有项目、任务、权限和系统操作记录，不做脱敏。</p><button class="secondary-button" onclick={exportLogs} disabled={exporting}>{exporting?'导出中…':'导出全局 CSV'}</button></section></div>{/if}{#if errorMessage}<div class="workspace-card error-state">{errorMessage}</div>{/if}
<style>.system-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.workspace-card h2{margin-top:0}.workspace-card p{color:var(--color-text-muted);line-height:1.7}.role-badge{display:inline-flex;padding:7px 10px;border-radius:999px;background:var(--color-primary-soft);color:var(--color-primary-strong);font-weight:600;font-size:12px}.error-state{color:var(--color-danger);margin-top:16px}.state-box{text-align:center;color:var(--color-text-muted)}@media(max-width:700px){.system-grid{grid-template-columns:1fr}}</style>
